from common import *
import shutil
assert not (R/'frozen_plan.json').exists(),'No overwrite'
receipt=json.load(open(SRC/'evidence/completed.json'));verify=json.load(open(SRC/'evidence/verification.json'));sourceplan=json.load(open(SRC/'frozen_plan.json'))
assert receipt['status']=='COMPLETED_S04_WAIT_FOR_JOINT_REVIEW' and verify['status']=='PASS','Prompt1 not completed; do not use old suffix'
assert sourceplan['suffix']=='\nDescription:'
run=json.load(open(SRC/'evidence/run_complete.json'));assert sha(SRC/'cache/new.npz')==run['cache_sha256']
