for src,dst in [(SRC/'data/panel.jsonl',R/'data/panel.jsonl'),(SRC/'cache/new.npz',R/'data/S04_frozen_activations.npz'),(SRC/'data/S03_frozen_selection.json',R/'data/S03_frozen_selection.json'),(SRC/'evidence/completed.json',R/'data/S04_completion.json'),(SRC/'evidence/run_complete.json',R/'data/S04_run_identity.json')]:shutil.copy2(src,dst)
