dump(R/'evidence/old_immutable_before.json',protected)
plan=dict(experiment=R.name,UTC=now(),authorization='Current direct user request authorizes offline SVD/geometric analysis of completed Prompt1=S04 frozen neutral-suffix cache. No model/SAE update, forwards, interventions or follow-up.',input_asset='analysis_r17_d1_s04_neutral_suffix_fixed24_20261103',source_suffix='\nDescription:',sites=SITES,scales=SCALES,primary_scale='raw_z',supplemental_scale='z*own_decoder_column_L2_norm',matrix_rows='AC:[F01P,F01cat,F02P,F02cat,F03P,F03cat]; AD:same P rows paired with dogs. Both6x30000, own exploration column means.',split={'exploration':['F01','F02','F03'],'heldout_check':['F04','F05','F06']},center='Each group own6-row exploration mean; saved. All24 samples projected as (x-mu_group)@V_group.T. Pair differences projected directly without subtracting any mean.',rank='Centered6rows rank<=5. Numerical rank tol=max(shape)*float64_eps*s1. Do not interpret null components.',comparisons={'PC1':'absolute cosine of leading right singular vectors; axes are unoriented','top2':'principal angles and normalized projection overlap ||V_AC[:2]@V_AD[:2].T||F^2/2','gaps':'all singular values, absolute/relative adjacent gaps; relative gap<0.1 marked small-gap descriptive warning, not a calibrated test'},orientation='For each direction, largest-absolute coefficient positive, ties lowest ID; flip all coefficients/scores as a group. Pair-difference cosine remains SIGNED.',top_members={'count_per_direction':5,'directions':[1,2],'ranking':'exploration absolute loading descending; ID ascending tie break. Both groups and scales separately, frozen before heldout projection.'},additional_members='All original S03 H2 atoms, ATTN14602/3516 explicitly; no importance rank implied.',near_zero='For vector cosine, ||v||<=1e-10*max(1,mean_exploration_row_L2_for_this_scale/site) is undefined, recorded null. No epsilon denominator.',bootstrap='Enumerate all27 ordered length3 family resamples with replacement from F01/F02/F03; same family sequence for AC/AD/P/C/D, keep labels and pairs. 10distinct unordered multisets, not27independent observations. Refit resampled exploration only; rank<k makes that metric undefined. Report count/min/5th/median/95th/max descriptively, not CI/p-values.',paired_differences='For all6families cat-P,dog-P; full30000vectors and exploration means. Project all onto both original exploration bases; compare signed cosine/lengths, heldout-to-exploration-mean direction. No holding refit.',decomposition='Disjoint per-family retained amplitude/new support/lost support differences; squared norm shares sum1 for each pair. Mean components can overlap across families, so save cross-dot3x3 contributions whose sum equals mean-difference signed cosine; never sum mean component energies as independent.',variance_accounting='For each fitted group/PC, exact totalSS=2*sum(family_midpoint_score^2)+0.5*sum((fine-P)_score^2); between-family midpoint and within-pair contributions are different.',counterexample='Choose first heldout family in fixed order with signed fine-P cosine to exploration mean<=0; else first own-basisPC1 paired projection reversing exploration mean sign; else first heldout cat-P vs dog-P cosine below exploration minimum; else report no counterexample meeting rule and show first check case without inventing failure. No heldout atom selection.',decoder_geometry='NOT_RUN: all main directions in same30000activation coordinates within each SAE. Weighting by norms is not the nonorthogonal decoder pullback metric; do not compare30000to1024.',data_SHA256={p.name:sha(p) for p in (R/'data').iterdir()},completion='All8matrix fits,exploration bootstrap,all24 projections,full paired differences/decomposition,top5members plus H2 values/texts,figures,bilingual summary and checks; STOP for joint review.',scope_exclusions=['new model forwards','SAE/model training','probe','new data/categories/prompts','intervention','H3/H4','cross-dictionary ID alignment','semantic/causal confirmation','automatic next experiment'])
dump(R/'frozen_plan.json',plan)
print('S05_INPUTS_AND_RULES_FROZEN',sha(R/'frozen_plan.json'),len(protected),flush=True)
